// Marsol Gemini Chatbot

document.addEventListener("DOMContentLoaded", function () {

    // Find the Chat with Marsol button
    const chatButton = document.querySelector(".marsol-chat-button");

    if (!chatButton) {
        console.log("Marsol chat button not found");
        return;
    }

    // Prevent duplicate chatbot
    if (document.getElementById("marsol-chat-box")) {
        return;
    }

    // ==============================
    // CREATE CHAT WINDOW
    // ==============================

    const chatBox = document.createElement("div");

    chatBox.id = "marsol-chat-box";

    chatBox.innerHTML = `
        <div class="marsol-chat-header">
            <span>🤖 Marsol Assistant</span>
            <button id="marsol-chat-close">×</button>
        </div>

        <div id="marsol-chat-messages">

            <div class="marsol-bot-message">
                Hi! 👋 I'm Marsol's AI assistant.
                <br><br>
                How can I help you today?
            </div>

        </div>

        <div class="marsol-chat-input-area">

            <input
                id="marsol-chat-input"
                type="text"
                placeholder="Ask something..."
                autocomplete="off"
            />

            <button id="marsol-chat-send">
                ➤
            </button>

        </div>
    `;

    document.body.appendChild(chatBox);


    // ==============================
    // CHATBOT CSS
    // ==============================

    const style = document.createElement("style");

    style.textContent = `

        #marsol-chat-box {

            position: fixed;

            right: 25px;
            bottom: 90px;

            width: 350px;
            height: 450px;

            background: #111;

            border: 1px solid #333;

            border-radius: 16px;

            z-index: 99999;

            display: none;

            flex-direction: column;

            overflow: hidden;

            box-shadow:
                0 10px 40px rgba(0,0,0,0.5);

            font-family: Arial, sans-serif;
        }


        /* HEADER */

        .marsol-chat-header {

            background: #cfff32;

            color: #111;

            padding: 16px;

            font-weight: bold;

            display: flex;

            justify-content: space-between;

            align-items: center;
        }


        .marsol-chat-header button {

            border: none;

            background: transparent;

            font-size: 25px;

            cursor: pointer;

            color: #111;
        }


        /* MESSAGE AREA */

        #marsol-chat-messages {

            flex: 1;

            padding: 15px;

            overflow-y: auto;

            color: white;

            background: #111;
        }


        /* BOT MESSAGE */

        .marsol-bot-message {

            background: #222;

            color: white;

            padding: 10px 12px;

            margin-bottom: 10px;

            border-radius: 10px;

            max-width: 85%;

            line-height: 1.4;

            word-wrap: break-word;
        }


        /* USER MESSAGE */

        .marsol-user-message {

            background: #cfff32;

            color: #111;

            padding: 10px 12px;

            margin-bottom: 10px;

            border-radius: 10px;

            max-width: 85%;

            margin-left: auto;

            line-height: 1.4;

            word-wrap: break-word;
        }


        /* INPUT AREA */

        .marsol-chat-input-area {

            display: flex;

            padding: 10px;

            border-top: 1px solid #333;

            gap: 8px;

            background: #111;
        }


        #marsol-chat-input {

            flex: 1;

            padding: 11px;

            border-radius: 8px;

            border: 1px solid #444;

            background: #222;

            color: white;

            outline: none;

            font-size: 14px;
        }


