        @media (max-width: 600px) {

            #marsol-chat-box {

                right: 10px;

                bottom: 80px;

                width: calc(100% - 20px);

                height: 450px;
            }
        }

    `;

    document.head.appendChild(style);


    // ==============================
    // OPEN CHATBOT
    // ==============================

    chatButton.addEventListener("click", function (event) {

        event.preventDefault();

        chatBox.style.display = "flex";

        const input =
            document.getElementById("marsol-chat-input");

        if (input) {

            input.focus();

        }

    });


    // ==============================
