    // ==============================
    // SEND MESSAGE
    // ==============================

    async function sendMessage() {

        const input =
            document.getElementById("marsol-chat-input");

        const messages =
            document.getElementById("marsol-chat-messages");

        const message =
            input.value.trim();


        // Don't send empty messages

        if (!message) {

            return;

        }


        // ==============================
        // SHOW USER MESSAGE
        // ==============================

        const userMessage =
            document.createElement("div");

        userMessage.className =
            "marsol-user-message";

        userMessage.textContent =
            message;

        messages.appendChild(userMessage);


        // Clear input

        input.value = "";


        // ==============================
        // SHOW LOADING
        // ==============================

        const loading =
            document.createElement("div");

        loading.id =
            "marsol-loading";

        loading.className =
            "marsol-bot-message";

        loading.textContent =
            "Thinking... 🤔";

        messages.appendChild(loading);


        messages.scrollTop =
            messages.scrollHeight;


        // ==============================
        // CALL FRAPPE + GEMINI API
        // ==============================

        try {

            const response = await fetch(

                "/api/method/marsol_website.api.chatbot.chat?message=" +
                encodeURIComponent(message),

                {

                    method: "GET",

                    credentials: "same-origin"

                }

            );


            // Check HTTP status

            if (!response.ok) {

                throw new Error(
                    "API request failed: " +
                    response.status
                );

            }


            // Convert response to JSON

            const result =
                await response.json();


            console.log(
                "Marsol Gemini response:",
                result
            );


            // Remove loading message

            if (loading) {

                loading.remove();

            }


            // Get Gemini response

            const reply =
                result.message?.reply;


            if (!reply) {

                throw new Error(
                    "No reply received from API"
                );

            }


            // ==============================
            // SHOW BOT RESPONSE
            // ==============================

            const botMessage =
                document.createElement("div");

            botMessage.className =
                "marsol-bot-message";

            botMessage.textContent =
                reply;

            messages.appendChild(
                botMessage
            );


            messages.scrollTop =
                messages.scrollHeight;


        }

        catch (error) {

            console.error(
                "Marsol chatbot error:",
                error
            );


            // Remove loading

            if (loading) {

                loading.remove();

            }


            // Show error

            const errorMessage =
                document.createElement("div");

            errorMessage.className =
                "marsol-bot-message";

            errorMessage.textContent =
                "Sorry, I couldn't connect to the assistant. Please try again.";

            messages.appendChild(
                errorMessage
            );


            messages.scrollTop =
                messages.scrollHeight;

        }

    }


    // ==============================
    // SEND BUTTON
    // ==============================

    document
        .getElementById("marsol-chat-send")
        .addEventListener(
            "click",
            sendMessage
        );


    // ==============================
    // ENTER KEY
    // ==============================

    document
        .getElementById("marsol-chat-input")
        .addEventListener(
            "keydown",
            function (event) {

                if (event.key === "Enter") {

                    event.preventDefault();

                    sendMessage();

                }

            }
        );

});

