document.addEventListener("DOMContentLoaded", function () {

    const searchButton = document.querySelector(".marsol-search-button");

    if (!searchButton) {
        console.log("Search button not found");
        return;
    }


    // Website pages database
    const pages = [
        {
            title: "Home",
            url: "/pages/homepage",
            content: "Marsol Technologies fire suppression systems engineered products"
        },
        {
            title: "Products",
            url: "/pages/product",
            content: "DIFF System DIFF Nozzles Self Contained Skid fire suppression products deck helideck"
        },
        {
            title: "Environmental",
            url: "/pages/environment",
            content: "Environmental services and solutions"
        },
        {
            title: "Careers",
            url: "/pages/career",
            content: "Careers jobs opportunities work with Marsol"
        }
    ];


    // Create search box
    const searchBox = document.createElement("div");

    searchBox.id = "marsol-search-box";

    searchBox.innerHTML = `
        <div class="marsol-search-title">
            Search Marsol
            <button id="marsol-search-close">×</button>
        </div>

        <input 
            id="marsol-search-input"
            placeholder="Search pages..."
        />

        <button id="marsol-search-submit">
            Search
        </button>

        <div id="marsol-search-results"></div>
    `;


    document.body.appendChild(searchBox);



    // CSS
    const style = document.createElement("style");

    style.textContent = `

    #marsol-search-box {
        position: fixed;
        top: 90px;
        right: 30px;
        width: 330px;
        background: white;
        color: black;
        border-radius: 12px;
        padding: 18px;
        z-index:99999;
        display:none;
        box-shadow:0 10px 35px rgba(0,0,0,0.25);
        font-family:Arial;
    }


    .marsol-search-title {
        font-size:18px;
        font-weight:bold;
        margin-bottom:15px;
        display:flex;
        justify-content:space-between;
    }


    #marsol-search-close {
        border:none;
        background:none;
        font-size:22px;
        cursor:pointer;
    }


    #marsol-search-input {

        width:100%;
        padding:12px;
        border:1px solid #ccc;
        border-radius:8px;
        margin-bottom:10px;
        box-sizing:border-box;

    }


    #marsol-search-submit {

        width:100%;
        padding:12px;
        background:#cfff32;
        border:none;
        border-radius:8px;
        font-weight:bold;
        cursor:pointer;

    }


    #marsol-search-results {

        margin-top:15px;

    }


    .marsol-result {

        padding:12px;
        border-bottom:1px solid #ddd;
        cursor:pointer;

    }


    .marsol-result:hover {

        background:#f3f3f3;

    }


    .marsol-no-result {

        color:#777;
        padding:10px;

    }

    `;


    document.head.appendChild(style);



    // Open search
    searchButton.addEventListener("click", function(e){

        e.preventDefault();

        searchBox.style.display="block";

        document
        .getElementById("marsol-search-input")
        .focus();

    });



    // Close
    document
    .getElementById("marsol-search-close")
    .onclick=function(){

        searchBox.style.display="none";

    };




    // Search function
    function performSearch(){

        const query =
        document
        .getElementById("marsol-search-input")
        .value
        .toLowerCase()
        .trim();


        const results =
        document.getElementById("marsol-search-results");


        results.innerHTML="";


        if(!query){

            results.innerHTML=
            `<div class="marsol-no-result">
            Type something to search
            </div>`;

            return;

        }



        const matches =
        pages.filter(page =>

            page.title.toLowerCase().includes(query) ||
            page.content.toLowerCase().includes(query)

        );



        if(matches.length===0){

            results.innerHTML=
            `<div class="marsol-no-result">
            No results found
            </div>`;

            return;

        }



        matches.forEach(page=>{


            const item =
            document.createElement("div");


            item.className="marsol-result";


            item.innerHTML=
            `
            <b>${page.title}</b>
            <br>
            <small>${page.content}</small>
            `;



            item.onclick=function(){

                window.location.href = page.url;

            };


            results.appendChild(item);


        });


    }




    document
    .getElementById("marsol-search-submit")
    .addEventListener(
        "click",
        performSearch
    );



    document
    .getElementById("marsol-search-input")
    .addEventListener(
        "keydown",
        function(e){

            if(e.key==="Enter"){
                performSearch();
            }

        }
    );


});

[data-theme-toggle]{cursor:pointer;transition:background-color .15s ease-out;}
[data-theme-toggle] .ti-sun{display:none;}
[data-theme-toggle] .ti-moon{display:inline-flex;}
:root[data-theme="dark"] [data-theme-toggle] .ti-sun{display:inline-flex;}
:root[data-theme="dark"] [data-theme-toggle] .ti-moon{display:none;}

(() => {
    const root = document.documentElement, KEY = "builder-theme";
    const system = () => window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
    root.setAttribute("data-theme", localStorage.getItem(KEY) || system());
    document.addEventListener("click", (e) => {
        const t = e.target.closest("[data-theme-toggle]");
        if (!t) return;
        const next = root.getAttribute("data-theme") === "dark" ? "light" : "dark";
        root.setAttribute("data-theme", next);
        localStorage.setItem(KEY, next);
    });
})();
